         ALLOWED_PARAMS.put("GridLayout", new String[]{"layout_width", "layout_height", "layout_margin", "layout_row", "layout_column", "layout_rowSpan", "layout_columnSpan", "layout_gravity"});
         ALLOWED_PARAMS.put("CoordinatorLayout", new String[]{"layout_width", "layout_height", "layout_margin", "layout_anchor", "layout_anchorGravity", "layout_behavior", "layout_keyline", "layout_insetEdge", "layout_dodgeInsetEdges"});
