         ALLOWED_PARAMS.put("TableLayout", new String[]{"layout_width", "layout_height", "layout_margin", "layout_column", "layout_span", "layout_gravity"}); // TableRow extends LinearLayout
         ALLOWED_PARAMS.put("TableRow", new String[]{"layout_width", "layout_height", "layout_margin", "layout_column", "layout_span", "layout_gravity"});
         ALLOWED_PARAMS.put("ViewPager", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("ViewPager2", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("ScrollView", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("HorizontalScrollView", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("NestedScrollView", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("RecyclerView", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("ListView", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("GridView", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("Toolbar", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity"});
         ALLOWED_PARAMS.put("AppBarLayout", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity", "layout_scrollFlags"});
         ALLOWED_PARAMS.put("CollapsingToolbarLayout", new String[]{"layout_width", "layout_height", "layout_margin", "layout_gravity", "layout_collapseMode", "layout_collapseParallaxMultiplier"});
         ALLOWED_PARAMS.put("MotionLayout", new String[]{"layout_width", "layout_height", "layout_margin", "layout_constraint", "layout_goneMargin", "layout_editor_absolute", "layout_optimization", "layout_wrapBehaviorInParent"});
