     Now, check validity:
     ```java
     String attrName = attribute.getLocalName();
     if (attrName == null) attrName = attribute.getName();
     if (!attrName.startsWith("layout_")) return;
     if (attrName.equals("layout_width") || attrName.equals("layout_height")) return; // Always valid

     String[] allowed = ALLOWED_PARAMS.get(parentTag);
     if (allowed == null) return; // Unknown parent, skip

     boolean valid = false;
     for (String prefix : allowed) {
         if (attrName.equals(prefix) || attrName.startsWith(prefix)) { // e.g., layout_marginLeft starts with layout_margin
             valid = true;
             break;
